[Form]
public class TFMDrawFlowTestDropDialog extends FormRun
{
    Map                             headerFieldsMap;
    FormButtonControl               fbc;
    Map                             regColControls;
    TFMRequestBasicElement          request;
    Map                             resultDataset;
    TFMProcess                      process;

}

public void init()
{

    TFMRegistrationCollector        regCol;
    FormStringControl               fst;
    Object                          caller = element.args().caller();
    process = caller.getProcess();

    TFMReferenceDataConfiguration   datCon = process.getHeaders();
    SetEnumerator                   sEnum = datCon.getCollectors().getEnumerator();

    super();
    headerFieldsMap = new Map(Types::String, Types::Class);
    while (sEnum.moveNext())
    {
        regCol = sEnum.current();
        if (!regCol.parmActive() || (regCol.parmLogicBlockConnected() && !regCol.parmDisableMatchedSource()))
        {
            continue;
        }
        fst = HeaderFields.addControl(FormControlType::String, regCol.parmName());
        headerFieldsMap.insert(fst.name(), fst);
        fst.label(regCol.parmLabel());
    }
    //element.control(element.controlId(formControlStr(TFMDrawFlowTestDropDialog,OkButton))).visible(false);
    fbc = element.design().addControl(FormControlType::Button,'acceptButton', HeaderFields);

    fbc.text("@TFM:Accept");

    fbc.registerOverrideMethod(methodStr(FormButtonControl, clicked), formMethodStr(TFMDrawFLowTestDropDialog, clickedAccept), this);
}

public void clickedAccept(FormButtonControl _formButtonControl)
{
    // Call registration Collectors
    MapEnumerator                                   mEnum = headerFieldsMap.getEnumerator();
    FormStringControl                               fst;        

    TFMRegistrationConfigurationResponseElement     responseElement;

    if (!process)
    {
        return;
    }

    request = new TFMRequestBasicElement();
    request.addField('ContentType', process.parmProcessName(),true);
    request.addField('DocumentType', TFMConstants::GetRegistrationConfiguration(), true);

    while (mEnum.moveNext())
    {
        fst = mEnum.currentValue();
        request.addField(fst.name(), fst.valueStr(), true);
    }


    responseElement = process.runProcess(request);
    while (HeaderFields.controlCount())
    {
        HeaderFields.formRun().design().removeControl(HeaderFields.controlNum(1).id());
    }

    regColControls = new Map (Types::String, Types::Class);
    //TODO: Change this part to "emulator"

    this.addControlsFromCollectors(responseElement.getCollectors());

    _formButtonControl.visible(false);

    fbc = element.design().addControl(FormControlType::Button,'postButton', HeaderFields);

    fbc.text("@TFM:Post");

    fbc.registerOverrideMethod(methodStr(FormButtonControl, clicked), formMethodStr(TFMDrawFLowTestDropDialog, clickedPost), this);

}

public void addControlsFromCollectors(TFMRegistrationCollectors _collectors)
{
    MapEnumerator               mEnum = _collectors.collectorMap().getEnumerator();
    FormStringControl           fst;
    TFMRegistrationCollector    regCol;
    while (mEnum.moveNext())
    {
        regCol = mEnum.currentValue();
        if (!regCol.parmActive())
        {
            continue;
        }
        fst = HeaderFields.addControl(FormControlType::String, regCol.parmName());
        fst.label(regCol.parmLabel());
        fst.text(regCol.parmDefaultValue());
        fst.visible(regCol.parmVisible());
        regColControls.insert(fst.name(), fst);
    }

    mEnum = _collectors.AdditionalValues().getEnumerator();
    while (mEnum.moveNext())
    {
        request.addField(mEnum.currentKey(), mEnum.currentValue(), true);
    }
}

public void clickedPost(FormButtonControl _formButtonControl)
{
    MapEnumerator                                   mEnum = regColControls.getEnumerator();
    FormStringControl                               fst;
    TFMResponseElement                              responseElement;
    TFMPostResponseData                             postResponseElement;
    TFMRegistrationConfigurationResponseElement     getConfResponseElement;

    while (mEnum.moveNext())
    {
        fst = mEnum.currentValue();
        request.addField(fst.name(), fst.valueStr(), true);            
    }
    request.addField('DocumentType', TFMConstants::PostAdhocRegistration(), true);

    if (!process)
    {
        return;
    }
    ttsbegin;
    responseElement = process.runProcess(request);

    if (responseElement is TFMRegistrationConfigurationResponseElement)
    {
        getConfResponseElement = responseElement;
        this.addControlsFromCollectors(getConfResponseElement.getCollectors());
        ttsabort;
        return;
    }
    postResponseElement = responseElement;
    resultDataset = this.getDataSet(request.logicContext().getDataContextMap() );
    info(postResponseElement.parmResponseText());
    ttsabort;
    _formButtonControl.visible(false);
    fbc = element.design().addControl(FormControlType::Button,'resultButton', HeaderFields);

    fbc.text("@TFM:ShowResults");

    fbc.registerOverrideMethod(methodStr(FormButtonControl, clicked), formMethodStr(TFMDrawFLowTestDropDialog, clickedShowResult), this);

}

protected Map getDataSet(Map _dataContext)
{
    MapEnumerator       mEnum = _dataContext.getEnumerator(), inlineMEnum;
    Map                 inlineDataContext;
    Map                 transferData = new Map(Types::String, Types::String);
    Common              data;
    while (mEnum.moveNext())
    {
        inlineDataContext = mEnum.currentValue();
        inlineMEnum = inlineDataContext.getEnumerator();
        while (inlineMEnum.moveNext())
        {
            data = inlineMEnum.currentValue();

            transferData.insert(TFMHelper::descriptionFromCommon(data), data.xml());
        }
    }
    return transferData;
}
